 "content": "from collections import deque


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # The full-color 2 bar marks the side toward which all objects settle.
    bar_rows = [r for r in range(h) if all(v == 2 for v in g[r])]
    if not bar_rows:
        raise ValueError("missing full-width 2 bar")
    direction = 1 if bar_rows[0] == 0 else -1

    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if g[r][c] in (0, 2) or (r, c) in seen:
                continue
            color = g[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and g[nr][nc] == color:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            objects.append((color, cells))

    # Move nearest-to-bar objects first; each object remains rigid.
    objects.sort(key=lambda obj: (min(r for r, _ in obj[1]) if direction == 1 else -max(r for r, _ in obj[1])))
    occupied = {(r, c) for r in range(h) for c in range(w) if g[r][c] == 2}
    placed = []
    for color, cells in objects:
        offset = 0
        while True:
            step = offset + direction
            can_move = True
            for r, c in cells:
                nr = r + step
                if not (0 <= nr < h) or (nr, c) in occupied:
                    can_move = False
                    break
            if not can_move:
                break
            offset = step
        moved = [(r + offset, c) for r, c in cells]
        placed.append((color, moved))
        occupied.update(moved)
    out = [[0] * w for _ in range(h)]
    for r, c in [(r, c) for r in range(h) for c in range(w) if g[r][c] == 2]:
        out[r][c] = 2
    for color, cells in placed:
        for r, c in cells:
            out[r][c] = color
    return out
